-- Test-only trigger in this rolled-back transaction; no production fault hooks.
create function public.nc_test_audit_failure() returns trigger language plpgsql as $$
begin if new.event_type='company.create' then raise exception 'PRIVATE_FAILURE_DETAIL'; end if; return new; end $$;
create trigger nc_test_failure before insert on public.audit_events for each row execute function public.nc_test_audit_failure();
create temporary table before_fault as select count(*) n from public.companies;
set local role authenticated;
select throws_ok('select public.security_v2_create_company(''d2000000-0000-4000-8000-000000000006'',''{"schemaVersion":1,"company":{"name":"Phase B test"},"contact":null,"services":[],"internal":{"lifecycleStatus":"onboarding","assignments":[]}}''::jsonb)','P0001','OPERATION_FAILED','Required audit failure rolls back, no internal details');
reset role;
select ok((select count(*) from public.companies)=(select n from before_fault),'No company after audit failure');
select ok(not exists(select 1 from private.provisioning_operations where idempotency_key='d2000000-0000-4000-8000-000000000006'),'Unknown failure rolls back operation too');
drop trigger nc_test_failure on public.audit_events;
drop function public.nc_test_audit_failure();
