select ok(not has_table_privilege('authenticated','public.companies','TRUNCATE'),'authenticated companies TRUNCATE denied');
select ok(not has_table_privilege('authenticated','public.companies','REFERENCES'),'authenticated companies REFERENCES denied');
select ok(not has_table_privilege('authenticated','public.companies','TRIGGER'),'authenticated companies TRIGGER denied');
set local role authenticated;
select throws_ok('insert into public.companies(name) values (''Bypass'')','42501',null,'Direct companies write denied');
select throws_ok('update public.companies set name=name','42501',null,'Direct companies write denied');
select throws_ok('delete from public.companies','42501',null,'Direct companies write denied');
select throws_ok('truncate public.companies','42501',null,'Direct companies write denied');
select ok(exists(select 1 from public.companies where id=(select (value->>'companyId')::uuid from results where label='full')),'Admin SELECT remains');
reset role;
select * from finish();
rollback;
